/**
 * Kernels: stateless services with one contract at their places (docs/local-platform.md § kernels).
 *
 *   POST <kernel>/v1/<op>  { inputs: { <name>: { id: <sha256 hex>, bytes?: <base64> } }, params }
 *                        → { outputs, result, ran: { kernel, build, place } }
 *   GET  <kernel>/v1/health → { kernel, build }
 *
 * `callKernel` is the one choice of where a call runs. The local host (backend.mjs), the local platform's worker
 * (api-worker 3d-design-eval.ts) and the SDKs' `Kernel` call it; each gives the transports it has. Pure: no network,
 * no file system. A transport is `(path, request) → Promise<{ status, body }>` (a GET when `request` is null: the
 * health), or it throws an error with `absent: true` when its kernel is not there (not installed, not configured).
 *
 * The rule of placement (fixed): the places of `kernels.<name>.place` are tried in order. A place with no transport, a
 * transport that is absent, a 404 (the kernel there has no such op) or a 503 `kernel_unavailable` falls to the next
 * place. Any other answer is the answer, a refusal of the op included: it is never sent again elsewhere.
 *
 * The places: `page` is the workbench page's own kernel (a Web Worker, packages/appkit/workbench/page-kernel.js), which
 * answers `observe` only, so every other op falls from it by the 404 rule; `local` is this computer's service; `cloud`
 * the platform's door. Only the page has a transport for `page`: every other caller passes it over.
 *
 * `ran.place` is set here, from the place the request went to, never from the answer. So a service on this computer
 * cannot call its result a cloud result, and a page result is never anything but the page's (docs/integrity.md
 * § kernel results).
 */
export const KERNEL_NAMES = Object.freeze(['3d', 'fea', 'slicer']);
export const KERNEL_PLACES = Object.freeze(['page', 'local', 'cloud']);
/** The page holds only the 3D kernel: the fea kernel's and the slicer's places begin on this computer. */
const DEFAULT_PLACES = Object.freeze({ '3d': Object.freeze(['page', 'local', 'cloud']), fea: Object.freeze(['local', 'cloud']), slicer: Object.freeze(['local', 'cloud']) });

/** Whether `v` is a valid value of `kernels.<name>.place`: a list of places, each at most once. */
export const validPlaces = v => Array.isArray(v) && v.length > 0 && v.every(p => KERNEL_PLACES.includes(p)) && new Set(v).size === v.length;

/**
 * The places to try, in order, from the setting's value (a list, or the same list as one text with commas: the form
 * an environment variable has). Undefined or null: the 3D kernel's page, then this computer, then the cloud (the fea kernel
 * and the slicer have no page).
 */
export function kernelPlaces(name, value) {
    if (!KERNEL_NAMES.includes(name))
        throw Error(`no kernel "${name}": one of ${KERNEL_NAMES.join(', ')}`);
    if (value === undefined || value === null || value === '')
        return [...DEFAULT_PLACES[name]];
    const list = typeof value === 'string' ? value.split(',').map(s => s.trim()).filter(Boolean) : value;
    if (!validPlaces(list))
        throw Error(`kernels.${name}.place is a list of ${KERNEL_PLACES.map(p => JSON.stringify(p)).join(', ')}, each at most once, not ${JSON.stringify(value)}`);
    return [...list];
}

const toBase64 = bytes => {
    let bin = '';
    for (let i = 0; i < bytes.length; i += 0x8000)
        bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
    return btoa(bin);
};
const hex = buf => [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');

/** A file as an input: its content id (sha256 of its bytes, hex) and its bytes (base64). `file`: text or bytes. */
export async function kernelFile(file) {
    const bytes = typeof file === 'string' ? new TextEncoder().encode(file) : file;
    return { id: hex(await crypto.subtle.digest('SHA-256', bytes)), bytes: toBase64(bytes) };
}

const plain = o => !!o && typeof o === 'object' && !Array.isArray(o);

/**
 * One call of `op` on kernel `kernel` → { status, body }, where body is the kernel's answer with `ran` set. `files`
 * are the inputs by name (text or bytes); `params` the op's own fields; `places` from kernelPlaces; `at` the
 * transports by place. When no place could run it: 503 `kernel_unavailable`, with each place and why. `op: "health"`
 * asks `GET /v1/health` of the first place that has the kernel.
 */
export async function callKernel({ kernel, op, files = {}, params = {}, places, at }) {
    if (!/^[a-z][a-z0-9-]{0,31}$/.test(op))
        return { status: 400, body: { error: `"${op}" is not an op name` } };
    let request = null;
    if (op !== 'health') {
        const inputs = {};
        for (const [name, file] of Object.entries(files))
            inputs[name] = await kernelFile(file);
        request = { inputs, params };
    }
    const tried = [];
    for (const place of places) {
        const send = at[place];
        if (!send) {
            tried.push({ place, why: 'no such place here' });
            continue;
        }
        let answer;
        try {
            answer = await send(`/v1/${op}`, request);
        }
        catch (e) {
            if (!e?.absent)
                throw e;
            tried.push({ place, why: e.message });
            continue;
        }
        const body = plain(answer.body) ? answer.body : { error: 'the kernel answered something that is not a JSON object' };
        if (answer.status === 404 || (answer.status === 503 && body.error === 'kernel_unavailable')) {
            tried.push({ place, why: answer.status === 404 ? `no op "${op}"` : String(body.reason ?? body.error) });
            continue;
        }
        // An op's answer names its build in `ran`; the health names it at the top.
        const build = plain(body.ran) && typeof body.ran.build === 'string' ? body.ran.build : typeof body.build === 'string' ? body.build : null;
        return { status: answer.status, body: { ...body, ran: { kernel, build, place } } };
    }
    return { status: 503, body: { error: 'kernel_unavailable', reason: `no place ran ${kernel} ${op}: ${tried.map(t => `${t.place}: ${t.why}`).join('; ') || 'no places'}`, tried } };
}
